// TH14 v1.00b Stage4 道中奖励编队：st04.ecl.txt MainSub05 (1175-1187)
// 敌 ECir03 (363-394) 与其发弹 helper ECir03_at (396-437)。
// 源起点为 MainSub05 卡帧0；上游 main160 与 Boss 存活/F门控按批准省略。

const TIME_LIMIT: int = 3024;
const OPENING_BUFFER: int = 120;
const WAVE_COUNT: int = 90;          // 源 $A = 90 的循环次数

// ECir03_at 的 EX 追加：ANIM(type2 a=1) -> BRIGHT(0x100000) -> WAIT(a=30)
// -> VELTIME(type 0x200000 a=60 r=%B s=-999999 保留角)。目标用 WAIT30 +
// 60 帧线性标量速率斜坡表达；每波 B 作为绑定参数快照进各自的弹。
xformdef VELTIME_RAMP(target: fx) {
    wait(30);
    step_speed(target, 60 + 65536 * EASE_LINEAR);
}

async sub ecir03_shooter() {
    // st04.ecl.txt:396-437
    wait(10);                          // 399
    var rank: int = global(GVAR_RANK);
    var groups: int = 8;               // 409 diffI($C, 1,2,5,8)
    var per_group: int = 4;            // 414 diffI($D, 1,2,3,4)
    var speed0: fx = 3fx;              // 413 diffF(%B, 2,2,2,3)
    var gap: int = 8;                  // 424-433 !E60 !N30 !H10 !LO8（L 取 8）
    if rank == RANK_EASY {
        groups = 1; per_group = 1; speed0 = 2fx; gap = 60;
    } else if rank == RANK_NORMAL {
        groups = 2; per_group = 2; speed0 = 2fx; gap = 30;
    } else if rank == RANK_HARD {
        groups = 5; per_group = 3; speed0 = 2fx; gap = 10;
    }
    for g in 0..groups {               // 404..852 外层：每轮重取自机角
        var aim: angle = aim_player();     // 412 etAngle(ANGLE_PLAYER, 20°)；N=1 时第二角不起作用
        var target: fx = speed0;           // 413
        for k in 0..per_group {            // 528 内层
            // ANIM 进入时 position -= 4*velocity：初速 0.2，退 0.8px
            var bx: fx = $self_x - 0.8fx * cos(aim);
            var by: fx = $self_y - 0.8fx * sin(aim);
            // 417 VELTIME(r=target) / 419 etOn / 420 %B += 0.4 / 421 wait(1)
            _ = fire(TH14_BIG_BALL, 4, bx, by, 0.2fx, aim, VELTIME_RAMP(target), none);
            target = target + 0.4fx;
            wait(1);
        }
        wait(gap);                         // 433 wait([-1])
    }
}

async sub ecir03() {
    // st04.ecl.txt:363-394
    set_invuln(65535);                 // 训练无敌外壳
    set_hurtbox(12fx);                 // 368 setHurtbox(24,24)：普通圆形取 24*0.5
    set_hitbox(8fx);                   // 369 setHitbox(16,16)：普通圆形取 16*0.5
    // 379-382：%A = FINAL_X/192 * 0.523599 - 1.570796；30° ≈ 5461 BAM
    var ratio: fx = $self_x / 192fx;
    var off: int = (ratio * 5461fx) as int;
    var dir: angle = (off as angle) - 90deg;
    move_vel(0, dir, 1fx, EASE_LINEAR);    // 382 moveVel(%A, 1.0)
    move_speed(120, 2fx, EASE_LINEAR);     // 383 moveSpeedTime(120, mode0, 2.0)
    wait(120);                              // 384
    // 385 flagClear(15)、386 anmColor 恢复：15 位无已核消费者，颜色属于纯表现
    spawn ecir03_shooter();                 // 387 @ECir03_at() async
    loop { wait(1000); }                    // 391-392：源主任务永不 delete
}

sub wave() {
    // st04.ecl.txt:1178-1185
    wait(60);                              // 1178
    for i in 0..WAVE_COUNT {
        // 1182 enmCreateF("ECir03", RANDF2*70, 400 + 64*RANDF2, 100, 1000, 1)
        var ux: int = rand(65536) - 32768;
        var sx: fx = (ux as fx) / 16384fx * 35fx;
        var uy: int = rand(65536) - 32768;
        var sy: fx = 400fx + (uy as fx) / 16384fx * 32fx;
        _ = spawn_enemy(sx, sy, 100, 1, 1000, 0, ecir03);
        wait(15);                          // 1183
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wave();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

